from dataclasses import dataclass

@dataclass(frozen=True)
class Answer:
    text: str
    source: str

def evaluate(cases: list[tuple[str, str]], answers: list[Answer]) -> float:
    correct = sum(expected in a.text for (_, expected), a in zip(cases, answers))
    return correct / len(cases)

cases = [("Qui exécute le bytecode ?", "JVM")]
answers = [Answer("La JVM exécute le bytecode", "JVM")]
print(f"Score d'évaluation: {evaluate(cases, answers):.0%}")
